import * as THREE from 'three/webgpu';
import { color, uv, mix, vec3 } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'editorial-oversized-type';
  const pos = config.scenePosition?.position ?? [0, 0, 0];
  const rot = config.scenePosition?.rotation ?? [0, 0, 0];
  const scl = config.scenePosition?.scale ?? [1, 1, 1];
  group.position.set(...pos);
  group.rotation.set(...rot);
  group.scale.set(...scl);

  const colors = {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38'
  };

  // Background plate with vertical engineered gradient
  const planeGeo = new THREE.PlaneGeometry(7, 5.5);
  const material = new THREE.MeshBasicNodeMaterial();
  const topColor = color(colors.background);
  const bottomColor = color(colors.surface);
  const vGrad = uv().y;
  material.colorNode = mix(topColor, bottomColor, vGrad);
  const plate = new THREE.Mesh(planeGeo, material);
  plate.position.set(0, 0, 0);
  plate.name = 'plate';
  group.add(plate);

  const disposables = [planeGeo, material];
  const timelines = [];
  const textNodes = [];

  function addText(str, opts) {
    const node = ctx.fontAtlas.createText(str, {
      family: opts.family,
      fontSize: opts.fontSize,
      fontWeight: opts.fontWeight,
      letterSpacing: opts.letterSpacing,
      lineHeight: opts.lineHeight,
      color: opts.color ?? colors.paper,
      align: 'left'
    });
    node.position.set(opts.x, opts.y, opts.z ?? 0.01);
    group.add(node);
    textNodes.push(node);
    return node;
  }

  // Kicker
  const kicker = addText('NOVA ATELIER / JOURNAL', {
    family: 'JetBrains Mono',
    fontSize: 18,
    fontWeight: 700,
    letterSpacing: 0.12,
    lineHeight: 1.4,
    x: -3.1,
    y: 1.7,
    color: colors.paper
  });

  // Hero letterpress shadow duplicates (behind, offset, ink color)
  const heroShadow1 = addText('PRECISION IS', {
    family: 'Lora',
    fontSize: 124,
    fontWeight: 600,
    letterSpacing: -0.015,
    lineHeight: 0.98,
    x: -3.1,
    y: 0.9,
    z: -0.01,
    color: colors.ink
  });
  const heroShadow2 = addText('A HABIT.', {
    family: 'Lora',
    fontSize: 124,
    fontWeight: 600,
    letterSpacing: -0.015,
    lineHeight: 0.98,
    x: -3.1,
    y: 0.25,
    z: -0.01,
    color: colors.ink
  });

  // Hero lines (front)
  const hero1 = addText('PRECISION IS', {
    family: 'Lora',
    fontSize: 124,
    fontWeight: 600,
    letterSpacing: -0.015,
    lineHeight: 0.98,
    x: -3.1,
    y: 0.9,
    z: 0.01,
    color: colors.paper
  });
  const hero2 = addText('A HABIT.', {
    family: 'Lora',
    fontSize: 124,
    fontWeight: 600,
    letterSpacing: -0.015,
    lineHeight: 0.98,
    x: -3.1,
    y: 0.25,
    z: 0.01,
    color: colors.paper
  });

  // Accent underline rule
  const ruleGeo = new THREE.PlaneGeometry(2.2, 0.05);
  const ruleMat = new THREE.MeshBasicNodeMaterial();
  ruleMat.colorNode = color(colors.accent);
  const rule = new THREE.Mesh(ruleGeo, ruleMat);
  rule.position.set(-3.1 + 2.2 / 2, -0.15, 0.01);
  rule.scale.x = 0;
  group.add(rule);
  disposables.push(ruleGeo, ruleMat);

  // Body paragraph
  const body = addText(
    'Notes from the bench: tolerances, tempering, and the case for slower watchmaking.',
    {
      family: 'JetBrains Mono',
      fontSize: 26,
      fontWeight: 400,
      letterSpacing: 0,
      lineHeight: 1.55,
      x: -3.1,
      y: -0.8,
      color: colors.paper
    }
  );

  // Caption
  const caption = addText('ISSUE 12 / JULY 2026', {
    family: 'JetBrains Mono',
    fontSize: 18,
    fontWeight: 400,
    letterSpacing: 0.08,
    lineHeight: 1.4,
    x: -3.1,
    y: -1.9,
    color: colors.paper
  });

  // Entrance animation: rise-in per block, top-to-bottom, 80ms stagger
  const blocks = [kicker, [heroShadow1, hero1], [heroShadow2, hero2], body, caption];
  const flat = [];
  blocks.forEach((b) => (Array.isArray(b) ? flat.push(...b) : flat.push(b)));

  flat.forEach((node) => {
    node.userData.baseY = node.position.y;
    node.position.y += 0.4;
    if (node.material) {
      node.material.transparent = true;
      node.material.opacity = 0;
    } else if (node.traverse) {
      node.traverse((c) => {
        if (c.material) {
          c.material.transparent = true;
          c.material.opacity = 0;
        }
      });
    }
  });

  const uniqueBlocks = [kicker, heroShadow1, hero1, heroShadow2, hero2, body, caption];
  uniqueBlocks.forEach((node, i) => {
    const tl = gsap.timeline({ delay: i * 0.08 });
    tl.to(node.position, {
      y: node.userData.baseY,
      duration: 0.7,
      ease: 'power3.out'
    }, 0);

    const opTarget = { v: 0 };
    tl.to(opTarget, {
      v: 1,
      duration: 0.7,
      ease: 'power3.out',
      onUpdate: () => {
        if (node.material) {
          node.material.opacity = opTarget.v;
        } else if (node.traverse) {
          node.traverse((c) => {
            if (c.material) c.material.opacity = opTarget.v;
          });
        }
      }
    }, 0);
    timelines.push(tl);
  });

  // Rule draws after hero lands
  const ruleTl = gsap.timeline({ delay: flat.length * 0.08 + 0.7 });
  ruleTl.to(rule.scale, {
    x: 1,
    duration: 0.5,
    ease: 'power2.out'
  });
  timelines.push(ruleTl);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    disposables.forEach((d) => d.dispose && d.dispose());
    textNodes.forEach((node) => {
      if (node.userData?.cleanup) node.userData.cleanup();
      if (node.geometry) node.geometry.dispose();
      if (node.material) node.material.dispose();
      node.traverse?.((c) => {
        if (c.geometry) c.geometry.dispose();
        if (c.material) c.material.dispose();
      });
    });
  };

  return group;
}
